/* ---- film 114 helpers ---- */
function ell114(cx, cy, rx, ry, col, a, lw = 1.5, rot = 0, dash = 0) {
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; if (dash) ctx.setLineDash([8, 7]); ctx.beginPath();
  ctx.ellipse(cx, cy, Math.max(rx, 0.1), Math.max(ry, 0.1), rot, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
}
function fillEll114(cx, cy, rx, ry, col, a) { if (a <= 0) return; ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore(); }
function interp114(arr, x) { if (x <= arr[0][0]) return arr[0][1]; for (let i = 1; i < arr.length; i++) if (x <= arr[i][0]) { const f = (x - arr[i - 1][0]) / (arr[i][0] - arr[i - 1][0]); return arr[i - 1][1] * (1 - f) + arr[i][1] * f; } return arr[arr.length - 1][1]; }
function axes114(px, py, pw, ph, xr, yr) { return [x => px + (x - xr[0]) / (xr[1] - xr[0]) * pw, y => py - (y - yr[0]) / (yr[1] - yr[0]) * ph]; }
function poly114(arr, xS, yS, col, a, lw = 3, prog = 1, j = 1) {
  if (a <= 0 || !arr.length) return;
  const n = Math.max(2, Math.min(arr.length, Math.floor(arr.length * prog)));
  strokePoly(arr.slice(0, n).map(p => [xS(p[0]), yS(p[j])]), col, a, lw, false);
}
function step114(arr, j, xS, yS, col, a, lw = 2.5) {
  if (a <= 0) return;
  const pts = [];
  for (let i = 0; i < arr.length; i++) { const p = arr[i]; if (i > 0 && p[j] !== arr[i - 1][j]) pts.push([xS(p[0]), yS(arr[i - 1][j])]); pts.push([xS(p[0]), yS(p[j])]); }
  strokePoly(pts, col, a, lw, false);
}
function tag114(s, x, y, a, col = C.green) { if (a <= 0) return; const w = tw(s, 15, F.mono, 700, 1) + 24; box(x - w, y - 20, w, 28, col, a, 1.2, 'rgba(0,30,15,0.6)'); txt(s, x - w / 2, y - 1, { size: 15, fam: F.mono, w: 700, align: 'center', c: col, a, ls: 1 }); }
/* the gauge sphere R = 1 and its dilations delta_R: (Rx, Ry, R^2 z); zs exaggerates the central direction */
function gauge114(cx, cy, s, ang, a, o = {}) {
  if (a <= 0) return;
  const zs = o.zs || 2.2, v = v3(cx, cy, s, ang, o.tilt == null ? 0.42 : o.tilt), col = o.col || C.cyan;
  (o.shells || [1]).forEach((R, si) => {
    const al = a * (si === 0 ? 1 : (o.sa || 0.4));
    for (let k = 0; k < 12; k++) { const th = Math.PI * k / 6, pts = []; for (let i = 0; i <= 40; i++) { const aa = -Math.PI / 2 + Math.PI * i / 40, r = R * Math.sqrt(Math.max(0, Math.cos(aa))); const p = v(r * Math.cos(th), r * Math.sin(th), zs * R * R * Math.sin(aa) / 4); pts.push([p[0], p[1]]); } strokePoly(pts, col, al * 0.5, 1.3, false); }
    [-1.15, -0.6, 0, 0.6, 1.15].forEach(aa => { const r = R * Math.sqrt(Math.cos(aa)), z = zs * R * R * Math.sin(aa) / 4, pts = []; for (let i = 0; i <= 48; i++) { const th = 2 * Math.PI * i / 48, p = v(r * Math.cos(th), r * Math.sin(th), z); pts.push([p[0], p[1]]); } strokePoly(pts, aa === 0 ? (o.eq || col) : col, al * (aa === 0 ? 0.95 : 0.4), aa === 0 ? 2.2 : 1.1, false); });
  });
  if (o.axis) { const R = (o.shells || [1])[0];[1, -1].forEach(sg => { const p = v(0, 0, zs * sg * R * R / 4); dot(p[0], p[1], 12, 'g', a * o.axis); }); }
}
/* the log cylinder (0,T) x J x T drawn as a tube */
function tube114(x0, y0, w, r, a, col = C.cyan, o = {}) {
  if (a <= 0) return;
  ell114(x0, y0, r * 0.32, r, col, a, 2);
  ell114(x0 + w, y0, r * 0.32, r, col, a * (o.seam ? 1 : 0.7), 2, 0, o.seam ? 0 : 1);
  line(x0, y0 - r, x0 + w, y0 - r, col, a, 2); line(x0, y0 + r, x0 + w, y0 + r, col, a, 2);
  for (let i = 1; i < 6; i++) dashed(x0 + w * i / 6, y0 - r, x0 + w * i / 6, y0 + r, C.dim, a * 0.35, 1);
}
const BETA114 = K_114.beta, S114 = K_114.s;
function lead114(x) { return 2 * (BETA114[0] * Math.cos(S114 * x) - BETA114[1] * Math.sin(S114 * x)); }
