SCENES.finale = S => {
  const u = S.u, t = S.t, L = [lineAt(S, 0), lineAt(S, 1)];
  badgeQ(S, [[0, null, 'theory'], [1, 'The heat-kernel formulas and the Hassell–Marshall comparison are published', 'published'], [1, 'the functional-analytic tools are classical', 'classical'], [1, 'the rest is argued in the theory volume', 'theory']]);
  const fade = 1 - clamp((u - L[1].e - 0.6) / 0.8);
  gauge114(W / 2, 600, 170, 0.5 + t * 0.2, Q(S, 0, 'A square-law Green error', 1.0) * (1 - Q(S, 1, 'The heat-kernel formulas', 0.6)) * 0.8, { shells: [1, 1.4, 1.8], axis: 1, sa: 0.3, zs: 1.0 });
  if (fade > 0) {
    const items = [['GREEN ERROR', 'C_n ε²', C.gold, 'A square-law Green error'], ['SEAM', '0 ≤ P − D ≤ r', C.mag, 'a bounded seam'], ['COUNT', 'L log(1/E) + O(1)', C.green, 'a bounded count'], ['CHANNEL', 'm = 0 , |σ| < s', C.cyan, 'one isolated channel'], ['OUTGOING', 'e^(isℓ) ψ', C.blue, 'an outgoing wave'], ['CORE', '2 Re(b e^(isℓ)) ψ', C.orange, 'a standing core wave'], ['WALL', '|β| = 1', C.red, 'a coupled wall'], ['FAMILY', 'one β , all E', C.vio, 'one exact family with one phase']];
    items.forEach(([a1, a2, col, ph], i) => { const x = 200 + i * 217, q = Q(S, 0, ph) * fade; box(x - 102, 240, 204, 130, col, q, 2, 'rgba(0,0,0,0.5)'); lbl(a1, x, 290, col, q, 17); lblG(a2, x, 338, C.white, q, 16); });
    lbl('PUBLISHED · heat-kernel formulas (Krötz–Thangavelu–Xu , math/0401243) · inverse-square counting comparison (Hassell–Marshall , math/0510617)', W / 2, 470, C.cyan, Q(S, 1, 'The heat-kernel formulas and the Hassell–Marshall comparison are published') * fade, 15);
    lbl('CLASSICAL · analytic Fredholm (Dyatlov–Zworski C.8) · min-max (Teschl 4.10) · Riesz , Fourier (Folland) · Fredholm perturbation (Kato IV.5) · Rellich', W / 2, 515, '#8fbcff', Q(S, 1, 'the functional-analytic tools are classical') * fade, 15);
    lbl('VOLUME · Theorem 20.2 · Corollaries 20.3–20.5 · Theorems 22.3 , 23.4 · Lemma 24.2 · Theorems 25.3 , 26.2 , 27.2 , 28.2 , 29.2 , 30.6', W / 2, 560, C.orange, Q(S, 1, 'the rest is argued in the theory volume') * fade, 15);
    lbl('RECOMPUTED (n = 2) · q₂ and C₂ = 7.16 · sup error ≈ ε²/2 · μ₂ = 0.8331 · s = 0.7443 at g = 8 · P − D ∈ {0,1} · arg β = 1.5429', W / 2, 605, C.white, Q(S, 1, 'the numbers for n equal two were recomputed') * fade, 15);
    lbl('NO LEAN-FROZEN DECLARATION IS USED IN THIS FILM · THE VOLUME HAS NO DIGESTION RECORDS', W / 2, 690, C.gold, Q(S, 1, 'the numbers for n equal two were recomputed', 0.6, 1.2) * fade, 20);
    lbl('open : the eigenvalue phase limit', W / 2, 740, C.vio, Q(S, 1, 'the numbers for n equal two were recomputed', 0.6, 1.6) * fade, 17);
  }
  const ep = clamp((u - L[1].e - 1.5) / 1.2);
  if (ep > 0) {
    const out = clamp((S.d - u) / 1.5), a = ep * out;
    gauge114(W / 2, 400, 230, 0.5 + t * 0.2, a, { shells: [1, 1.5], axis: 1, sa: 0.3, zs: 1.3 });
    txt('ATTRACTIVE BOUNDARY II', W / 2, 680, { size: 56, fam: F.orb, w: 900, align: 'center', c: '#f4fbff', a, ab: 5, ls: 5 });
    txt('FIB 原生吸引边界响应 第二部 · 格林尾、有界计数与墙相位 · TRURETURING FILM 114', W / 2, 750, { size: 30, fam: F.zh, w: 700, align: 'center', c: C.gold, a });
    txt('github.com/the-omega-institute/trureturing', W / 2, 815, { size: 34, fam: F.mono, w: 700, align: 'center', c: C.cyan, a: clamp((u - L[1].e - 2.4) / 0.8) * out });
    txt('One square-law error, one bounded count, one negative channel, and one phase shared by every small energy.', W / 2, 875, { size: 26, fam: F.raj, w: 600, align: 'center', c: C.white, a: clamp((u - L[1].e - 3.2) / 0.8) * out });
  }
};

Object.assign(NAMES, { open: 'ATTRACTIVE BOUNDARY II', marginal: 'COMPLETE MARGINAL', tail: 'EXTERIOR TAIL', count: 'COUNTING BOUNDARY', seam: 'BOUNDED SEAM', transfer: 'BOUNDED COUNT', channel: 'ONE CHANNEL', outgoing: 'OUTGOING WAVE', core: 'CORE STANDING WAVE', wall: 'COUPLED WALL', family: 'ONE PHASE FAMILY', finale: 'LEDGER' });

